], (response) => {
  // Handle events here
});
```

### 4. Event Branching Logic
```typescript
(response) => {
  const isRowEvent = response.channels.some(
    c => c.startsWith(`tablesdb.${DATABASE_ID}`)
  );
  const isFileEvent = response.channels.some(
    c => c.startsWith(`buckets.${BUCKET_ID}`)
  );

  if (isRowEvent) {
    handleRowEvent(response);
  }

  if (isFileEvent) {
    handleFileEvent(response);
  }
}
```

### 5. Complete Implementation with Handlers
```typescript
import { Client, Realtime, Channel } from 'appwrite';

const DATABASE_ID = '[DATABASE_ID]';
const TABLE_ID   = '[TABLE_ID]';
const BUCKET_ID  = '[BUCKET_ID]';

const client = new Client()
  .setEndpoint('https://<REGION>.cloud.appwrite.io/v1')
  .setProject('[PROJECT_ID]');

const realtime = new Realtime(client);

function handleRowEvent(response: RealtimeResponseEvent<any>) {
  const { events, payload } = response;

  if (events.some(e => e.includes('.create'))) {
    console.log('✅ Row created:', payload);
    // e.g. insert into local state
  } else if (events.some(e => e.includes('.update'))) {
    console.log('✏️  Row updated:', payload);
    // e.g. merge into local state
  } else if (events.some(e => e.includes('.delete'))) {
    console.log('🗑️  Row deleted:', payload);
    // e.g. remove from local state
  }
}

function handleFileEvent(response: RealtimeResponseEvent<any>) {
  const { events, payload } = response;

  if (events.some(e => e.includes('.create'))) {
    console.log('📁 File uploaded:', payload.name, payload.mimeType);
    // e.g. refresh file list
  } else if (events.some(e => e.includes('.delete'))) {
    console.log('🗑️  File deleted:', payload.$id);
    // e.g. remove from file list
  }
}

// ─── Subscribe ────────────────────────────────────────────────────────────────
const subscription = await realtime.subscribe(
  [
    Channel.tablesdb(DATABASE_ID).table(TABLE_ID).row(),
    Channel.bucket(BUCKET_ID).file(),
  ],
  (response) => {
    const isRowEvent  = response.channels.some(c => c.startsWith(`tablesdb.${DATABASE_ID}`));
    const isFileEvent = response.channels.some(c => c.startsWith(`buckets.${BUCKET_ID}`));

    if (isRowEvent)  handleRowEvent(response);
    if (isFileEvent) handleFileEvent(response);
  }
);

// ─── Cleanup ──────────────────────────────────────────────────────────────────
// Call when component unmounts or subscription is no longer needed
// await subscription.close();
```

## Response Object Shape

```typescript
interface RealtimeResponseEvent<T> {
  events:    string[];   // e.g. ["databases.*.collections.*.documents.*.create"]
  channels:  string[];   // e.g. ["tablesdb.DB_ID.tables.TABLE_ID.rows"]
  payload:   T;          // The actual row or file document
  timestamp: string;     // ISO 8601 timestamp
}
```

## Why Branch on `response.channels` Instead of `response.events`?

| Approach | Pros | Cons |
|---|---|---|
| `response.channels` | Directly maps to your subscription channels | Slightly more verbose |
| `response.events` | Event strings contain resource type info | Event format may change; harder to parse |

Using `response.channels` is more **explicit and stable** — you know exactly which subscription triggered the callback.

