## 2. Browser code — `appwrite` Web SDK

```typescript
import { Client, TablesDB, ID, Permission, Role, AppwriteException } from 'appwrite';

const client = new Client()
    .setEndpoint('https://<REGION>.cloud.appwrite.io/v1')
    .setProject('[PROJECT_ID]');

const tablesDB = new TablesDB(client);

const DATABASE_ID = 'main';
const TABLE_ID = 'tasks';

interface Task {
    title: string;
    completed: boolean;
    dueDate: string; // ISO 8601
}

export async function createTask(userId: string, title: string, due: Date) {
    try {
        return await tablesDB.createRow({
            databaseId: DATABASE_ID,
            tableId: TABLE_ID,
            rowId: ID.unique(),
            data: {
                title,
                completed: false,
                dueDate: due.toISOString(), // datetime columns take ISO 8601 strings
            } satisfies Task,
            permissions: [
                Permission.read(Role.user(userId)),
                Permission.update(Role.user(userId)),
                Permission.delete(Role.user(userId)),
            ],
        });
    } catch (err) {
        if (err instanceof AppwriteException) {
            console.error(err.code, err.type, err.message);
        }
        throw err;
    }
}
```

Reading it back:

```typescript
import { Query } from 'appwrite';

const page = await tablesDB.listRows({
    databaseId: DATABASE_ID,
    tableId: TABLE_ID,
    queries: [
        Query.equal('completed', false),
        Query.orderAsc('dueDate'),
        Query.limit(25),
    ],
});

page.rows.forEach(r => console.log(r.$id, r.title, r.dueDate));
```

The row insert requires an authenticated session (or a `Role.any()` create permission on the table) — with the permissions above, a guest will get a `401`.

