createTask().catch(console.error);
```

`dueDate` must be an ISO 8601 datetime string.

Use `TablesDB.listRows()` and pass `Query` expressions through the `queries` array. Appwrite applies multiple top-level queries with **AND** semantics.

```ts
import { Client, TablesDB, Query } from 'appwrite';
// Server-side: import from 'node-appwrite'

const client = new Client()
  .setEndpoint('https://<REGION>.cloud.appwrite.io/v1')
  .setProject('[PROJECT_ID]');

const tablesDB = new TablesDB(client);
```

## Filtering

```ts
const result = await tablesDB.listRows({
  databaseId: '[DATABASE_ID]',
  tableId: '[TABLE_ID]',
  queries: [
    Query.equal('status', 'published'),
    Query.greaterThanEqual('price', 10),
    Query.lessThan('price', 100),
  ],
});

console.log(result.rows);
console.log(result.total);
```

Common filters include:

```ts
Query.equal('status', 'active');
Query.notEqual('status', 'archived');

Query.greaterThan('price', 10);
Query.greaterThanEqual('price', 10);
Query.lessThan('price', 100);
Query.lessThanEqual('price', 100);
Query.between('price', 10, 100);

Query.isNull('deletedAt');
Query.isNotNull('publishedAt');

Query.startsWith('title', 'Appwrite');
Query.endsWith('filename', '.pdf');
Query.contains('tags', 'typescript');

// Requires a full-text index
Query.search('content', 'backend database');
```

Pass multiple values to `equal()` for an IN-style query:

```ts
Query.equal('status', ['draft', 'published']);
```

Use `Query.or()` when filters should be ORed:

```ts
queries: [
  Query.or([
    Query.equal('status', 'published'),
    Query.equal('featured', true),
  ]),
];
```

## Sorting

```ts
const result = await tablesDB.listRows({
  databaseId: '[DATABASE_ID]',
  tableId: '[TABLE_ID]',
  queries: [
    Query.equal('status', 'published'),
    Query.orderDesc('$createdAt'),
    Query.orderAsc('title'),
  ],
});
```

- `Query.orderAsc('column')` sorts ascending.
- `Query.orderDesc('column')` sorts descending.
- Multiple order queries define primary and secondary sorting.

## Limiting results

```ts
const result = await tablesDB.listRows({
  databaseId: '[DATABASE_ID]',
  tableId: '[TABLE_ID]',
  queries: [
    Query.orderDesc('$createdAt'),
    Query.limit(10),
  ],
});
```

The default limit is 25 rows; the maximum per request is 100.

## Offset pagination

Offset pagination is convenient for numbered pages:

```ts
const page = 3;
const pageSize = 20;

const result = await tablesDB.listRows({
  databaseId: '[DATABASE_ID]',
  tableId: '[TABLE_ID]',
  queries: [
    Query.orderDesc('$createdAt'),
    Query.limit(pageSize),
    Query.offset((page - 1) * pageSize),
  ],
});
```

Offset pagination becomes less efficient for large offsets and can shift when rows are inserted or deleted.

## Cursor pagination

Cursor pagination is preferred for large or frequently changing datasets.

```ts
const pageSize = 20;

// First page
const firstPage = await tablesDB.listRows({
  databaseId: '[DATABASE_ID]',
  tableId: '[TABLE_ID]',
  queries: [
    Query.orderDesc('$createdAt'),
    Query.limit(pageSize),
  ],
});

const lastRow = firstPage.rows.at(-1);

// Next page
const nextPage = lastRow
  ? await tablesDB.listRows({
      databaseId: '[DATABASE_ID]',
      tableId: '[TABLE_ID]',
      queries: [
        Query.orderDesc('$createdAt'), // Keep the same ordering
        Query.limit(pageSize),
        Query.cursorAfter(lastRow.$id),
      ],
    })
  : null;
```

For backward pagination:

```ts
Query.cursorBefore('[ROW_ID]');
```

Do not combine cursor and offset pagination in the same request. Keep filters and sorting identical between cursor-based page requests.

## Complete example

```ts
const result = await tablesDB.listRows({
  databaseId: '[DATABASE_ID]',
  tableId: '[TABLE_ID]',
  queries: [
    Query.equal('status', ['published', 'scheduled']),
    Query.greaterThanEqual('rating', 4),
    Query.contains('tags', 'appwrite'),
    Query.orderDesc('$createdAt'),
    Query.limit(25),
  ],
});

for (const row of result.rows) {
  console.log(row.$id, row.title);
}
```

Filtered and sorted columns should have appropriate indexes; `Query.search()` specifically requires a full-text index. Row and table permissions still apply, so only rows readable by the current user are returned.

Use `Query.greaterThan()` for the numeric filter, `Query.orderDesc()` for descending order, and `Query.limit()` to cap the result count:

```typescript
import { Query } from 'appwrite';

const results = await tablesDB.listRows({
  databaseId: '[DATABASE_ID]',
  tableId: '[TABLE_ID]',
  queries: [
    Query.greaterThan('score', 100),
    Query.orderDesc('score'),
    Query.limit(20),
  ],
});
```

This returns up to 20 rows where `score > 100`, ordered from highest to lowest score. The `score` column must be numeric; indexing it is recommended for efficient filtering and sorting.

