```

Bucket creation is an administrative operation and is **not available through the Appwrite Web SDK**. Create the bucket once using the Console or Server SDK; never expose an API key in browser code. Then use the Web SDK to upload files and generate preview URLs.

## 1. Create the bucket server-side

Install:

```bash
npm install node-appwrite
```

```ts
// create-bucket.ts
import {
  Client,
  Storage,
  Permission,
  Role,
} from 'node-appwrite';

const client = new Client()
  .setEndpoint(process.env.APPWRITE_ENDPOINT!) // e.g. https://<REGION>.cloud.appwrite.io/v1
  .setProject(process.env.APPWRITE_PROJECT_ID!)
  .setKey(process.env.APPWRITE_API_KEY!); // Requires buckets.write scope

const storage = new Storage(client);

await storage.createBucket({
  bucketId: 'images',
  name: 'Images',
  enabled: true,

  // Required for per-file permissions used below.
  fileSecurity: true,

  // Any authenticated user may upload files.
  permissions: [
    Permission.create(Role.users()),
  ],

  maximumFileSize: 10 * 1024 * 1024,
  allowedFileExtensions: ['jpg', 'jpeg', 'png', 'gif', 'webp'],
});

console.log('Bucket created');
```

Keep the API key only in server-side environment variables.

## 2. Upload and preview with the Web SDK

Install:

```bash
npm install appwrite
```

```ts
import {
  Account,
  Client,
  ID,
  Permission,
  Role,
  Storage,
} from 'appwrite';

const BUCKET_ID = 'images';

const client = new Client()
  .setEndpoint('https://<REGION>.cloud.appwrite.io/v1')
  .setProject('<PROJECT_ID>');

const account = new Account(client);
const storage = new Storage(client);

export async function uploadImage(file: File) {
  if (!file.type.startsWith('image/')) {
    throw new Error('Please select an image file.');
  }

  // Assumes the user already has an Appwrite session.
  const user = await account.get();

  const uploadedFile = await storage.createFile({
    bucketId: BUCKET_ID,
    fileId: ID.unique(),
    file,
    permissions: [
      Permission.read(Role.user(user.$id)),
      Permission.update(Role.user(user.$id)),
      Permission.delete(Role.user(user.$id)),
    ],
  });

  const previewUrl = storage.getFilePreview({
    bucketId: BUCKET_ID,
    fileId: uploadedFile.$id,
    width: 800,
    height: 800,
    quality: 85,
  });

  return {
    file: uploadedFile,
    previewUrl: previewUrl.toString(),
  };
}
```

Example usage:

```ts
const input = document.querySelector<HTMLInputElement>('#image-input')!;
const preview = document.querySelector<HTMLImageElement>('#image-preview')!;

input.addEventListener('change', async () => {
  const selectedFile = input.files?.[0];
  if (!selectedFile) return;

  try {
    const result = await uploadImage(selectedFile);
    preview.src = result.previewUrl;
  } catch (error) {
    console.error('Upload failed:', error);
  }
});
```

```html
<input id="image-input" type="file" accept="image/*" />
<img id="image-preview" alt="Uploaded image preview" />
```

The example makes each file private to its owner. To make previews publicly accessible, replace the file’s read permission with:

```ts
Permission.read(Role.any())
```

Avoid granting `update` or `delete` permissions to `Role.any()`.

```ts
import { Client, Realtime, Channel, Models } from 'appwrite';

const DATABASE_ID = 'YOUR_DATABASE_ID';
const TABLE_ID = 'YOUR_TABLE_ID';
const BUCKET_ID = 'YOUR_BUCKET_ID';

const client = new Client()
  .setEndpoint('https://<REGION>.cloud.appwrite.io/v1')
  .setProject('YOUR_PROJECT_ID');

const realtime = new Realtime(client);

type TaskRow = {
  $id: string;
  $createdAt: string;
  $updatedAt: string;
  title: string;
  completed: boolean;
};

async function subscribeToChanges() {
  const rowsChannel = Channel.tablesdb(DATABASE_ID)
    .table(TABLE_ID)
    .row();

  const filesChannel = Channel.bucket(BUCKET_ID).file();

  const subscription = await realtime.subscribe(
    [rowsChannel, filesChannel],
    (response) => {
      const isCreate = response.events.some((event) =>
        event.endsWith('.create')
      );
      const isUpdate = response.events.some((event) =>
        event.endsWith('.update')
      );
      const isDelete = response.events.some((event) =>
        event.endsWith('.delete')
      );

      // Handle table row changes.
      if (response.channels.includes(rowsChannel)) {
        const row = response.payload as TaskRow;

        if (isCreate) {
          console.log('Row created:', row);
          addRowToUI(row);
        } else if (isUpdate) {
          console.log('Row updated:', row);
          updateRowInUI(row);
        } else if (isDelete) {
          console.log('Row deleted:', row.$id);
          removeRowFromUI(row.$id);
        }

        return;
      }

      // A file upload produces a file ".create" event.
      if (response.channels.includes(filesChannel) && isCreate) {
        const file = response.payload as Models.File;

        console.log('File uploaded:', file);
        showUploadedFile({
          id: file.$id,
          name: file.name,
          mimeType: file.mimeType,
          size: file.sizeOriginal,
        });
      }
    }
  );

  // Call this when the page/component is disposed.
  return async () => {
    await subscription.close();
  };
}

// Application-specific handlers
function addRowToUI(row: TaskRow) {
  // ...
}

function updateRowInUI(row: TaskRow) {
  // ...
}

function removeRowFromUI(rowId: string) {
  // ...
}

function showUploadedFile(file: {
  id: string;
  name: string;
  mimeType: string;
  size: number;
}) {
  // ...
}

const unsubscribe = await subscribeToChanges();

// Later:
// await unsubscribe();
```

The current user must have read permission for the rows and files; Appwrite Realtime only delivers events for resources the user can access. File updates and deletions are ignored here because only `.create` represents a new upload.

