Database and table creation are **server-side-only** operations. Do not run provisioning code in a browser or expose an API key. The current TablesDB API is:

```ts
// server/provision-tasks.ts
import { Client, TablesDB, ID } from 'node-appwrite';

const client = new Client()
  .setEndpoint(process.env.APPWRITE_ENDPOINT!) // e.g. https://<REGION>.cloud.appwrite.io/v1
  .setProject(process.env.APPWRITE_PROJECT_ID!)
  .setKey(process.env.APPWRITE_API_KEY!); // Needs database/table management scopes

const tablesDB = new TablesDB(client);

async function createTasksSchema() {
  // 1. Create a database
  const database = await tablesDB.create({
    databaseId: ID.unique(),
    name: 'Task Database',
  });

  // 2. Create the tasks table and its columns
  const tasksTable = await tablesDB.createTable({
    databaseId: database.$id,
    tableId: 'tasks',
    name: 'Tasks',
    columns: [
      {
        key: 'title',
        type: 'varchar',
        size: 255,
        required: true,
      },
      {
        key: 'completed',
        type: 'boolean',
        required: true,
        default: false,
      },
      {
        key: 'dueDate',
        type: 'datetime',
        required: false,
      },
    ],
  });

  // 3. Insert a row
  const task = await tablesDB.createRow({
    databaseId: database.$id,
    tableId: tasksTable.$id,
    rowId: ID.unique(),
    data: {
      title: 'Ship the Tasks feature',
      completed: false,
      dueDate: '2025-04-15T09:00:00.000Z', // ISO 8601 datetime
    },
  });

  console.log({ database, tasksTable, task });
}

createTasksSchema().catch(console.error);
```

