  databaseId: '<DATABASE_ID>',
  tableId: '<TABLE_ID>',
  queries: [
    Query.equal('status', 'published'),
    Query.limit(20),
  ],
});

console.log(result.total); // total matching rows
console.log(result.rows);  // rows returned for this request
```

## Filtering

Each query in the array is combined with **AND** by default.

```ts
const result = await tablesDB.listRows({
  databaseId: '<DATABASE_ID>',
  tableId: 'products',
  queries: [
    Query.equal('status', 'active'),
    Query.greaterThanEqual('price', 20),
    Query.lessThan('price', 100),
    Query.isNotNull('imageId'),
  ],
});
```

Common filters:

```ts
Query.equal('status', 'active');
Query.notEqual('status', 'archived');

Query.lessThan('price', 100);
Query.lessThanEqual('price', 100);
Query.greaterThan('rating', 4);
Query.greaterThanEqual('rating', 4);

Query.between('price', 10, 50);       // inclusive: 10 <= price <= 50
Query.isNull('deletedAt');
Query.isNotNull('ownerId');

Query.startsWith('slug', 'appwrite-');
Query.endsWith('email', '@example.com');
Query.contains('tags', 'typescript'); // works for suitable string/array columns
```

Pass an array to `equal` to match **any** listed value:

```ts
const result = await tablesDB.listRows({
  databaseId: '<DATABASE_ID>',
  tableId: 'tasks',
  queries: [
    Query.equal('status', ['open', 'in_progress']),
  ],
});
```

That is equivalent to:

```text
status = "open" OR status = "in_progress"
```

For full-text matching, use `Query.search`. The column needs a full-text index.

```ts
const result = await tablesDB.listRows({
  databaseId: '<DATABASE_ID>',
  tableId: 'articles',
  queries: [
    Query.search('title', 'tables database'),
  ],
});
```

## Sorting

Use `Query.orderAsc()` or `Query.orderDesc()`.

```ts
const result = await tablesDB.listRows({
  databaseId: '<DATABASE_ID>',
  tableId: 'products',
  queries: [
    Query.equal('status', 'active'),
    Query.orderDesc('price'),
    Query.limit(10),
  ],
});
```

Multiple sort queries create secondary ordering:

```ts
const result = await tablesDB.listRows({
  databaseId: '<DATABASE_ID>',
  tableId: 'tasks',
  queries: [
    Query.orderAsc('priority'),
    Query.orderDesc('$createdAt'),
    Query.limit(25),
  ],
});
```

This orders by lowest `priority` first, then newest rows first when priorities are equal.

## Limiting and offset pagination

`Query.limit()` controls the number of rows returned. The default is 25 and the maximum is 100.

```ts
const pageSize = 25;
const pageNumber = 3; // one-based

const result = await tablesDB.listRows({
  databaseId: '<DATABASE_ID>',
  tableId: 'orders',
  queries: [
    Query.orderDesc('$createdAt'),
    Query.limit(pageSize),
    Query.offset((pageNumber - 1) * pageSize),
  ],
});
```

Offset pagination is convenient for numbered pages, but it becomes less efficient for large offsets and can shift when rows are inserted or removed.

## Cursor pagination

For feeds, infinite scrolling, or large tables, prefer cursor pagination. Fetch a page, then use the last returned row’s `$id` as the cursor for the next page.

```ts
const pageSize = 20;

const firstPage = await tablesDB.listRows({
  databaseId: '<DATABASE_ID>',
  tableId: 'posts',
  queries: [
    Query.equal('status', 'published'),
    Query.orderDesc('$createdAt'),
    Query.orderDesc('$id'), // stable tie-breaker
    Query.limit(pageSize),
  ],
});

const rows = firstPage.rows;
const lastRow = rows.at(-1);
```

Fetch the next page:

```ts
const nextPage = lastRow
  ? await tablesDB.listRows({
      databaseId: '<DATABASE_ID>',
      tableId: 'posts',
      queries: [
        Query.equal('status', 'published'),
        Query.orderDesc('$createdAt'),
        Query.orderDesc('$id'),
        Query.limit(pageSize),
        Query.cursorAfter(lastRow.$id),
      ],
    })
  : { rows: [], total: 0 };
```

To load the preceding page, use the first row of the current page:

```ts
const firstRow = rows.at(0);

const previousPage = firstRow
  ? await tablesDB.listRows({
      databaseId: '<DATABASE_ID>',
      tableId: 'posts',
      queries: [
        Query.equal('status', 'published'),
        Query.orderDesc('$createdAt'),
        Query.orderDesc('$id'),
        Query.limit(pageSize),
        Query.cursorBefore(firstRow.$id),
      ],
    })
  : { rows: [], total: 0 };
```

Keep the filter and sort queries identical between cursor requests. Do not combine cursor pagination with `Query.offset()`.

## Practical notes

- Query values must match the column type—for example, use numbers for numeric columns and booleans for boolean columns.
- Create appropriate indexes for fields you filter or sort by. `Query.search()` specifically requires a full-text index.
- Results are also constrained by the caller’s table and row permissions; a query returns only rows the current client is allowed to read.

Use `Query.greaterThan`, `Query.orderDesc`, and `Query.limit` in the `queries` array:

```ts
import { Query } from 'appwrite';

const results = await tablesDB.listRows({
  databaseId: '[DATABASE_ID]',
  tableId: '[TABLE_ID]',
  queries: [
    Query.greaterThan('score', 100),
    Query.orderDesc('score'),
    Query.limit(20),
  ],
});
```

This returns up to 20 rows whose numeric `score` field is strictly greater than `100`, ordered from highest to lowest score. Replace `score` with your numeric column key.

```js
// src/main.js
export default async ({ req, res, error }) => {
  const { name } = req.bodyJson ?? {};

  if (typeof name !== 'string' || !name.trim()) {
    error('Missing or invalid "name" field');

    return res.json(
      { error: 'The "name" field is required.' },
      400
    );
  }

  return res.json({
    message: `Hello, ${name.trim()}!`,
  });
};
```

For example, invoking the function with:

```json
{ "name": "Ada" }
```

returns HTTP `200`:

```json
{ "message": "Hello, Ada!" }
```

`createBucket` is an administrative operation. Do **not** expose an API key in a browser. In production, create the bucket once from the Appwrite Console, a Function, or a trusted server. The Web SDK code below assumes the caller is an authorized project administrator when provisioning the bucket; normal users only need permission to upload files.

```ts
import {
  Account,
  Client,
  ID,
  Permission,
  Role,
  Storage,
} from "appwrite";

const client = new Client()
  .setEndpoint("https://<REGION>.cloud.appwrite.io/v1")
  .setProject("<PROJECT_ID>");

const storage = new Storage(client);
const account = new Account(client);

const BUCKET_ID = "image-uploads";

/**
 * Run once from a trusted/admin context.
 *
 * - Authenticated users can upload.
 * - File-level permissions are enabled.
 * - Individual uploaded images control who can read/update/delete them.
 */
export async function createImageBucket() {
  return storage.createBucket({
    bucketId: BUCKET_ID,
    name: "Image uploads",
    fileSecurity: true,
    enabled: true,
    maximumFileSize: 10 * 1024 * 1024, // 10 MB
    allowedFileExtensions: ["jpg", "jpeg", "png", "webp", "gif"],
    permissions: [
      // Allows signed-in application users to create files in this bucket.
      Permission.create(Role.users()),
    ],
  });
}

/**
 * The current user must be signed in, and the bucket must already exist.
 */
export async function uploadImageAndGetPreview(image: File) {
  if (!image.type.startsWith("image/")) {
    throw new Error("Please select an image file.");
  }

  const currentUser = await account.get();

  const uploadedFile = await storage.createFile({
    bucketId: BUCKET_ID,
    fileId: ID.unique(),
    file: image,
    permissions: [
      // Makes the image and generated preview publicly viewable.
      Permission.read(Role.any()),

      // Only the uploader can change or remove this file.
      Permission.update(Role.user(currentUser.$id)),
      Permission.delete(Role.user(currentUser.$id)),
    ],
  });

  // This is synchronous: it constructs a URL; it does not fetch the image.
  const previewUrl = storage.getFilePreview({
    bucketId: BUCKET_ID,
    fileId: uploadedFile.$id,
    width: 800,
    height: 800,
  });

  return {
    file: uploadedFile,
    previewUrl: previewUrl.toString(),
  };
}
```

Example usage with a file input:

```ts
const input = document.querySelector<HTMLInputElement>("#image-input")!;
const preview = document.querySelector<HTMLImageElement>("#preview")!;

input.addEventListener("change", async () => {
  const image = input.files?.[0];
  if (!image) return;

  const { previewUrl } = await uploadImageAndGetPreview(image);
  preview.src = previewUrl;
});
```

```html
<input id="image-input" type="file" accept="image/*" />
<img id="preview" alt="Uploaded image preview" />
```

`Permission.read(Role.any())` makes both the source image and its preview public. For private images, replace it with `Permission.read(Role.user(currentUser.$id))` (or an appropriate team role).

Appwrite Messaging supports these **push providers**:

- **Firebase Cloud Messaging (FCM)** — Android, Web Push, and Firebase-managed iOS delivery.
- **Apple Push Notification service (APNs)** — native Apple-platform delivery.

> Email and SMS use separate Messaging providers; the two above are the push-notification providers.

## 1. Configure a provider

In the Appwrite Console, open **Messaging → Providers → Create provider**:

- For **FCM**, create/download a Firebase service-account key from Firebase Console and add it as an FCM provider.
- For **APNs**, create an APNs authentication key in the Apple Developer portal and provide its key, key ID, team ID, and bundle ID as requested.

Save the provider and note its **provider ID**. Keep Firebase service-account JSON and Apple private keys only in the Appwrite provider configuration—never in an app client.

## 2. Register each device as a push target

Your app obtains a platform push token using its native push library (for example, Firebase Messaging on Android/Web or APNs on iOS). Then register that token with Appwrite against the configured provider.

For an authenticated user registering their own device:

```ts
import { Client, Account, ID } from 'react-native-appwrite';
// Use `appwrite` for web

const client = new Client()
  .setEndpoint('https://<REGION>.cloud.appwrite.io/v1')
  .setProject('<PROJECT_ID>');

const account = new Account(client);

const target = await account.createPushTarget({
  targetId: ID.unique(),
  identifier: devicePushToken,      // token from FCM or APNs
  providerId: '<PUSH_PROVIDER_ID>', // provider created in Console
});
```

A backend or Appwrite Function can also create a target for a specified user with the server SDK:

```ts
await messaging.createPushTarget({
  targetId: ID.unique(),
  userId: '<USER_ID>',
  identifier: devicePushToken,
  providerId: '<PUSH_PROVIDER_ID>',
});
```

Refresh or replace the target when the device token changes.

## 3. Create a topic and subscribe targets

A Messaging topic is an Appwrite-managed audience. It is not necessary to send separately through FCM and APNs: Appwrite finds each subscribed target and routes through that target’s provider.

Create a topic once, either in the Console or with the server SDK:

```ts
const topic = await messaging.createTopic({
  topicId: 'product-updates',
  name: 'Product updates',
});
```

Subscribe a registered push target:

```ts
await messaging.subscribeTopic({
  topicId: 'product-updates',
  targetId: target.$id,
});
```

Ensure the topic’s subscription permissions permit the intended users or perform subscriptions from trusted backend code.

## 4. Send a push notification to the topic

Send from a trusted server or an Appwrite Function using an API key with the appropriate Messaging write permissions:

```ts
import { Client, Messaging, ID } from 'node-appwrite';

const client = new Client()
  .setEndpoint('https://<REGION>.cloud.appwrite.io/v1')
  .setProject(process.env.APPWRITE_PROJECT_ID!)
  .setKey(process.env.APPWRITE_API_KEY!);

const messaging = new Messaging(client);

await messaging.createPush({
  messageId: ID.unique(),
  title: 'New product update',
  body: 'Version 2.0 is now available.',
  topics: ['product-updates'], // Appwrite topic IDs, not topic names
  data: {
    route: '/updates/2.0',
    version: '2.0',
  },
});
```

Appwrite will fan out that message to every subscribed **push target** and deliver it through its associated FCM or APNs provider.

Key points:

- A target represents one app installation/device token.
- A user may have multiple targets, such as an iPhone and Android phone.
- One target may subscribe to multiple topics.
- Send with `topics: ['<TOPIC_ID>']`; do not put Firebase/APNs provider credentials in the sender code.

Appwrite Messaging resolves recipients through three selector types, available on `createEmail`, `createSms`, and `createPush`:

- **`users`** — Appwrite Auth user IDs. Appwrite delivers through that user’s eligible target(s) for the selected channel.
- **`topics`** — Messaging topic IDs. Appwrite delivers to every target subscribed to the topic.
- **`targets`** — Messaging target IDs. This is the most precise option: one email address, phone number, or push-device token registered with a Messaging provider.

The selectors can be supplied together when creating a message. IDs—not raw email addresses, phone numbers, or push tokens—belong in these arrays.

```ts
import { Client, Messaging, ID } from 'node-appwrite';

const client = new Client()
  .setEndpoint(process.env.APPWRITE_ENDPOINT!)
  .setProject(process.env.APPWRITE_PROJECT_ID!)
  .setKey(process.env.APPWRITE_API_KEY!);

const messaging = new Messaging(client);
```

### Send to particular users

Use Appwrite Auth user IDs:

```ts
await messaging.createEmail({
  messageId: ID.unique(),
  subject: 'Your report is ready',
  content: 'Your monthly report is now available.',
  users: ['user_123', 'user_456'],
});
```

For an SMS or push message, use the same `users` field with `createSms` or `createPush`. Appwrite uses destinations that are valid for that message channel.

### Send to a topic

A topic is a named audience. Targets subscribe to it, and a message sent to that topic reaches its subscribers.

```ts
await messaging.createPush({
  messageId: ID.unique(),
  title: 'New release',
  body: 'Version 2.0 is available now.',
  topics: ['product-updates'],
});
```

To make a target receive topic messages, create a subscriber that links the target to the topic:

```ts
await messaging.createSubscriber({
  subscriberId: ID.unique(),
  topicId: 'product-updates',
  targetId: 'target_device_123',
});
```

### Send to one exact destination

First register a Messaging **target** with the appropriate provider. For example, a push target uses a device token and a configured push provider:

```ts
const target = await messaging.createTarget({
  targetId: ID.unique(),
  userId: 'user_123',
  providerId: 'fcm-provider',
  identifier: 'FCM_DEVICE_TOKEN',
});
```

Then address that target directly:

```ts
await messaging.createPush({
  messageId: ID.unique(),
  title: 'Security alert',
  body: 'A sign-in was detected on your account.',
  targets: [target.$id],
});
```

The same pattern applies to email and SMS targets: create a target with the relevant email/SMS provider and its identifier, then provide its target ID in `targets`.

```ts
import { Client, Realtime, Channel } from 'appwrite';

const DATABASE_ID = 'your-database-id';
const TABLE_ID = 'your-table-id';
const BUCKET_ID = 'your-bucket-id';

const client = new Client()
  .setEndpoint('https://<REGION>.cloud.appwrite.io/v1')
  .setProject('your-project-id');

const realtime = new Realtime(client);

const subscription = await realtime.subscribe(
  [
    // All row create/update/delete events for this table
    Channel.tablesdb(DATABASE_ID).table(TABLE_ID).row(),

    // All file create/update/delete events for this bucket
    Channel.bucket(BUCKET_ID).file(),
  ],
  (response) => {
    const isTableRowEvent = response.events.some((event) =>
      event.startsWith('tablesdb.')
    );

    const isFileEvent = response.events.some((event) =>
      event.startsWith('buckets.')
    );

    if (isTableRowEvent) {
      const row = response.payload;

      if (response.events.some((event) => event.endsWith('.create'))) {
        console.log('A table row was created:', row);
        // e.g. add the row to your UI state
      } else if (response.events.some((event) => event.endsWith('.update'))) {
        console.log('A table row was updated:', row);
        // e.g. replace the matching row in your UI state
      } else if (response.events.some((event) => event.endsWith('.delete'))) {
        console.log('A table row was deleted:', row);
        // e.g. remove the row from your UI state
      }

      return;
    }

    if (isFileEvent) {
      const file = response.payload;

      if (response.events.some((event) => event.endsWith('.create'))) {
        console.log('A file was uploaded:', file);
        // e.g. show an upload notification or add it to a file gallery
      } else if (response.events.some((event) => event.endsWith('.update'))) {
        console.log('A file was updated:', file);
      } else if (response.events.some((event) => event.endsWith('.delete'))) {
        console.log('A file was deleted:', file);
      }
    }
  }
);

// Call this when the component/page is disposed.
async function stopRealtime() {
  await subscription.close();
}
```

The current user must have read permission for the relevant table rows and files; otherwise their realtime events will not be delivered.

```ts
const unsubscribe = realtime.subscribe(
  [
    'tablesdb.[DATABASE_ID].tables.[TABLE_ID].rows',
    'buckets.[BUCKET_ID].files',
  ],
  (response) => {
    console.log(response.events, response.payload);
  }
);
```

Exact channel formats:

- Table rows: `tablesdb.<DATABASE_ID>.tables.<TABLE_ID>.rows`
- Bucket files: `buckets.<BUCKET_ID>.files`
